static int mkdirs(const char *path)
{
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "%s", path);
    for (char *p = tmp + 1; *p; p++) {
        if (*p == '/') {
            *p = '\0';
            mkdir(tmp, 0700);
            *p = '/';
        }
    }
    mkdir(tmp, 0700);
    return OK;
}

static cJSON *load_json(void)
{
    FILE *f = fopen(AGENT_CONFIG_FILE, "r");
    if (!f) return cJSON_CreateObject();

    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (sz <= 0) { fclose(f); return cJSON_CreateObject(); }

    char *buf = (char *)malloc((size_t)(sz + 1));
    if (!buf) { fclose(f); return cJSON_CreateObject(); }

    size_t n = fread(buf, 1, (size_t)sz, f);
    buf[n] = '\0';
    fclose(f);

    cJSON *root = cJSON_Parse(buf);
    free(buf);
    return root ? root : cJSON_CreateObject();
}

static int save_json(cJSON *root)
{
    char *str = cJSON_PrintUnformatted(root);
    if (!str) return ERROR;

    /* Use open() with explicit 0600 to ensure config file is owner-only.
     * fopen("w") inherits umask which may be too permissive. */
    int fd = open(AGENT_CONFIG_FILE,
                  O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (fd < 0) { free(str); return ERROR; }

    FILE *f = fdopen(fd, "w");
    if (!f) { close(fd); free(str); return ERROR; }
    fputs(str, f);
    fclose(f);
    free(str);
/* Create directory if not exists (recursive) */
static int ensure_dir(const char *path)
{
    struct stat st = {0};
    if (stat(path, &st) == -1) {
        /* Try to create parent first */
        char parent[256];
        strncpy(parent, path, sizeof(parent) - 1);
        char *slash = strrchr(parent, '/');
        if (slash && slash != parent) {
            *slash = '\0';
            if (ensure_dir(parent) != OK) return ERROR;
        }

        if (mkdir(path, 0755) == -1) {
            syslog(LOG_ERR, "[%s] mkdir failed for %s, errno=%d\n", TAG, path, errno);
            return ERROR;
        }
        syslog(LOG_INFO, "[%s] Created directory: %s\n", TAG, path);
    }
    return OK;
}

/* Create file with initial content if not exists */
static int ensure_file(const char *path, const char *default_content)
{
    struct stat st = {0};
    if (stat(path, &st) == -1) {
        /* File does not exist, create it */
        FILE *f = fopen(path, "w");
        if (!f) {
            syslog(LOG_ERR, "[%s] Cannot create %s, errno=%d\n", TAG, path, errno);
            return ERROR;
        }
        if (default_content) {
            fputs(default_content, f);
        }
        fclose(f);
        syslog(LOG_INFO, "[%s] Created file: %s\n", TAG, path);
    }

